contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address baseToken,
        address nft,
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoy
    ) public {
        require(feeRate <= 5_000);

        c.initialize(
            baseToken,
            nft,
            vBase,
            vNft,
            changeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoy
        );

        bool secondReverted;
        try c.initialize(
            address(1), address(2), 1, 1, 0, 0, bytes32(0), false, false
        ) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(
            c.initialized() &&
            secondReverted &&
            c.baseToken() == baseToken &&
            c.nft() == nft &&
            c.virtualBaseTokenReserves() == vBase &&
            c.virtualNftReserves() == vNft &&
            c.changeFee() == changeFee &&
            c.feeRate() == feeRate &&
            c.merkleRoot() == merkleRoot &&
            c.useStolenNftOracle() == useOracle &&
            c.payRoyalties() == payRoy
        );
    }
}

