contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint16 feeRate, uint128 vBase, uint128 vNft, uint128 outputAmount) public payable {
        require(feeRate <= 5000);
        require(vNft > outputAmount);
        require(vBase > 0);

        c.initialize(address(0), address(0), vBase, vNft, 0, feeRate, bytes32(0), false, false);

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);

        uint256 gross = FixedPointMathLib.mulDivUp(outputAmount, vBase, uint256(vNft) - uint256(outputAmount));
        uint256 protoRate = Factory(c.factory()).protocolFeeRate();
        uint256 expFee = gross * feeRate / 10_000;
        uint256 expProto = gross * protoRate / 10_000;

        assert(netInputAmount == gross + feeAmount + protocolFeeAmount
            && feeAmount == expFee
            && protocolFeeAmount == expProto
            && netInputAmount >= gross);
    }
}

