contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights
    ) public view {
        // Fresh pool: merkleRoot is bytes32(0), so no proof is needed.
        bytes32[] memory proofArr = new bytes32[](0);
        bool[] memory flagsArr = new bool[](0);
        C.MerkleMultiProof memory proof = C.MerkleMultiProof(proofArr, flagsArr);

        // View call, cannot revert for any inputs.
        uint256 sum = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, proof);

        assert(sum == tokenIds.length * 1e18);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        require(_feeRate > 5000 || _feeRate <= 5000);

        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (_feeRate > 5000) {
            assert(reverted && c.initialized() == false);
        } else {
            assert(!reverted && c.initialized() && c.feeRate() == _feeRate && c.baseToken() == _baseToken && c.nft() == _nft);
        }
    }
}

