contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 vBase,
        uint128 vNft,
        uint16 feeRate,
        uint128 outputAmount
    ) public {
        require(feeRate <= 5000);
        require(outputAmount < vNft);
        require(vBase < (1 << 100) && vNft < (1 << 100) && outputAmount < (1 << 100));

        c.initialize(
            address(0),
            address(0x1),
            vBase,
            vNft,
            0,
            feeRate,
            bytes32(0),
            false,
            false
        );

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);

        uint256 denom = uint256(vNft - outputAmount);
        uint256 expectedInput = (uint256(outputAmount) * uint256(vBase) + denom - 1) / denom;

        assert(
            netInputAmount == expectedInput + feeAmount + protocolFeeAmount &&
            feeAmount * 10000 <= expectedInput * uint256(feeRate) &&
            expectedInput * uint256(feeRate) - feeAmount * 10000 < 10000 &&
            netInputAmount >= feeAmount + protocolFeeAmount
        );
    }
}
